function pretty(json, indent){ try{ var o=JSON.parse(json); return JSON.stringify(o, null, indent||2); }catch(e){ return {error:e.message}; } }
function minify(json){ try{ var o=JSON.parse(json); return JSON.stringify(o); }catch(e){ return {error:e.message}; } }
function validate(json){ try{ JSON.parse(json); return {valid:true}; }catch(e){ return {valid:false, error:e.message}; } }
var EXPORTS={pretty:pretty, minify:minify, validate:validate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.JsonFormatForgePure = EXPORTS; }
